fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let nx = x.len();
    let ny = y.len();

    // Preallocate the output matrices with the correct number of rows.
    let mut x_mat: Vec<Vec<f32>> = Vec::with_capacity(ny);
    let mut y_mat: Vec<Vec<f32>> = Vec::with_capacity(ny);

    for &yv in &y {
        // Each row of x_mat is a clone of x.
        x_mat.push(x.clone());
        // Each row of y_mat is yv repeated nx times.
        y_mat.push(vec![yv; nx]);
    }

    (x_mat, y_mat)
}

